// Package invariants serves the behavioural guarantees this system
// claims, each anchored to the test that proves it.
//
// The JSON is generated by apps/api/cmd/invariants from the doc
// comments of annotated tests, and that generator's own test fails the
// build when the committed file stops matching the test suite. So this
// page cannot quietly describe a guarantee the code stopped making —
// which is the only reason a page like this is worth publishing.
package invariants

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"sync"
)

//go:embed invariants.json
var raw []byte

// Invariant is one published guarantee and its proof.
type Invariant struct {
	Statement string `json:"statement"`
	Category  string `json:"category"`
	// Attack and Refused are what make a guarantee legible to someone
	// who cannot open the repository: what a person would try, and what
	// the system does instead. A file and line is an address; this is
	// the argument.
	Attack  string `json:"attack,omitempty"`
	Refused string `json:"refused,omitempty"`
	Test    string `json:"test"`
	File    string `json:"file"`
	Line    int    `json:"line"`
	Package string `json:"package"`
}

// HasExample reports whether this invariant can show its own worked
// attack. Used by the page so an unannotated one degrades to the
// statement rather than rendering an empty box.
func (i Invariant) HasExample() bool { return i.Attack != "" && i.Refused != "" }

// Location renders the proof's address the way a reader would paste it
// into an editor.
func (i Invariant) Location() string { return fmt.Sprintf("%s:%d", i.File, i.Line) }

// Group is one category with its invariants, in published order.
type Group struct {
	Category   string
	Invariants []Invariant
}

// Label is the human heading for a category. Unknown categories render
// as themselves rather than being dropped, so adding one to a test does
// not silently hide it from the page.
func (g Group) Label() string {
	switch g.Category {
	case "authority":
		return "Authority cannot be self-asserted"
	case "isolation":
		return "One tenant cannot reach another"
	case "evidence":
		return "The record cannot quietly disagree with what happened"
	case "coverage":
		return "What the gate never saw is reported, not assumed absent"
	case "accounting":
		return "Authority is counted once, and never past a total"
	case "failure-modes":
		return "What happens when something breaks"
	default:
		return g.Category
	}
}

type document struct {
	Source     string      `json:"source"`
	Count      int         `json:"count"`
	Invariants []Invariant `json:"invariants"`
}

var (
	once   sync.Once
	parsed document
	perr   error
)

func load() (document, error) {
	once.Do(func() { perr = json.Unmarshal(raw, &parsed) })
	return parsed, perr
}

// All returns every published invariant.
func All() ([]Invariant, error) {
	d, err := load()
	if err != nil {
		return nil, err
	}
	return d.Invariants, nil
}

// Count is how many guarantees are published.
func Count() int {
	d, err := load()
	if err != nil {
		return 0
	}
	return d.Count
}

// Source names the module the invariants were extracted from, so the
// page can state the scope of the claim instead of implying it covers
// every repository.
func Source() string {
	d, _ := load()
	return d.Source
}

// Grouped returns the invariants by category. Category order is fixed
// rather than alphabetical: authority and isolation are what a security
// reviewer opens the page for.
func Grouped() ([]Group, error) {
	all, err := All()
	if err != nil {
		return nil, err
	}
	order := map[string]int{"authority": 0, "isolation": 1, "evidence": 2, "coverage": 3, "failure-modes": 4}
	byCat := map[string][]Invariant{}
	for _, inv := range all {
		byCat[inv.Category] = append(byCat[inv.Category], inv)
	}
	groups := make([]Group, 0, len(byCat))
	for cat, list := range byCat {
		groups = append(groups, Group{Category: cat, Invariants: list})
	}
	sort.SliceStable(groups, func(i, j int) bool {
		oi, oki := order[groups[i].Category]
		oj, okj := order[groups[j].Category]
		if oki != okj {
			return oki // known categories before unknown ones
		}
		if oki && okj && oi != oj {
			return oi < oj
		}
		return groups[i].Category < groups[j].Category
	})
	return groups, nil
}
